	private static void assertWeak(Snapshot counters, long ordinary, long recovered, long other, long joint,
			long factor) {
		assertThat(new long[] { counters.ordinaryWeak(), counters.ordinaryWeakRecovered(),
				counters.ordinaryWeakTerminalOther(), counters.jointWeakTerminal(), counters.factorWeakTerminal() })
				.as("qualified-observer: actual ordinary/factor weak outcome")
				.containsExactly(ordinary, recovered, other, joint, factor);
		assertThat(counters.ordinaryWeak()).isEqualTo(counters.ordinaryWeakRecovered()
				+ counters.ordinaryWeakTerminalOther() + counters.jointWeakTerminal());
		assertThat(counters.jointWeakTerminal()).isLessThanOrEqualTo(counters.factorWeakTerminal());
	}

	private void assertOneOwner() {
		assertThat(PublicationQualifiedAccounting.opened())
				.as("qualified-observer: one materializer opened").isEqualTo(1L);
		assertThat(PublicationQualifiedAccounting.closed())
				.as("qualified-observer: one materializer closed").isEqualTo(1L);
		assertThat(PublicationQualifiedAccounting.size())
				.as("qualified-observer: one primitive record exported").isEqualTo(1);
		assertThat(PublicationQualifiedAccounting.overflowCount()).isZero();
		assertThat(snapshot().ownerOrdinal()).as("qualified-observer: first owner identity").isEqualTo(1L);
		assertThat(snapshot().compileOrdinalAtOpen()).isEqualTo(compileBaseline);
		assertThat(snapshot().compileOrdinalAtClose()).isEqualTo(compileBaseline);
		assertThat(snapshot().lazyValueCallsAtOpen()).isEqualTo(resolverBaseline);
		assertThat(snapshot().lazyValueCallsAtClose()).isEqualTo(LmdbNativeExpressionCompiler.LAZY_VALUE_CALLS.get());
	}

	private static void requireCollected(WeakReference<Value> reference) {
		for (int attempt = 0; attempt < 24 && !reference.refersTo(null); attempt++) {
			System.gc();
		}
		assertThat(reference.refersTo(null))
				.as("Required weak referent was not collected; this contract must fail rather than skip")
				.isTrue();
	}

