	private static final class Coordinates implements NativeResultCoordinates {
		long position;

		@Override
		public long coordinateActivation() {
			return 1L;
		}

		@Override
		public boolean resultCoordinate(int slot, long[] coordinate) {
			if (slot != 0) {
				return false;
			}
			coordinate[NAMESPACE] = 1L;
			coordinate[GROUP] = 1L;
			coordinate[PARENT] = 2L;
			coordinate[COLUMN] = 0L;
			coordinate[POSITION] = position;
			return true;
		}
	}

	private static final class CountingSource implements NativeLmdbQuerySource {
		final Map<Long, Value> values = new HashMap<>();
		final List<Long> calls = new ArrayList<>();
		Object scope = new Object();
		int scopeCalls;
		int changeAtScopeCall = -1;
		boolean closed;

		Value replace(long id) {
			Value replacement = VF.createBNode("value-" + id);
			values.put(id, replacement);
			return replacement;
		}

		void changeScopeAtNextValidation() {
			changeAtScopeCall = scopeCalls + 2;
		}

		@Override
		public Object resultValueScope() {
			if (closed) {
				throw new AssertionError("Closed source scope consulted");
			}
			if (++scopeCalls == changeAtScopeCall) {
				scope = new Object();
			}
			return scope;
		}

		@Override
		public long idOf(Value value) {
			throw new UnsupportedOperationException();
		}

		@Override
		public Value lazyValue(long id) {
			return lazyValue(id, ValuePosition.OBJECT);
		}

		@Override
		public Value lazyValue(long id, int positionMask) {
			if (closed) {
				throw new AssertionError("Closed source resolution consulted");
			}
			assertThat(positionMask).isEqualTo(ValuePosition.OBJECT);
			LmdbNativeExpressionCompiler.LAZY_VALUE_CALLS.incrementAndGet();
			calls.add(id);
			Value value = values.get(id);
			if (value == null) {
				throw new AssertionError("Unexpected source lookup " + id);
			}
			return value;
		}

		@Override
		public Object idSpace() {
			return this;
		}

		@Override
		public RecordIterator statements(long subject, long predicate, long object, long context) {
			throw new UnsupportedOperationException();
		}

		@Override
		public long count(long subject, long predicate, long object, long context) {
			throw new UnsupportedOperationException();
		}

		@Override
		public boolean has(long subject, long predicate, long object, long context) {
			throw new UnsupportedOperationException();
		}

		@Override
		public double estimate(long subject, long predicate, long object, long context) {
			throw new UnsupportedOperationException();
		}

		@Override
		public boolean hasStatementsInSource() {
			throw new UnsupportedOperationException();
		}
	}
